package com.andye.warmod.warhead;
import com.andye.warmod.icbm.IcbmChunkTicketRegistry; import com.andye.warmod.icbm.IcbmConstants; import java.util.*; import net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents; import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents; import net.minecraft.server.MinecraftServer; import net.minecraft.server.level.ServerLevel; import net.minecraft.world.level.ChunkPos; import net.minecraft.world.phys.Vec3;
public final class WarheadImpactChunkLeaseManager { private static final Map<ServerLevel,Map<UUID,Lease>> LEASES=new WeakHashMap<>();private static boolean registered;private WarheadImpactChunkLeaseManager(){} public static void registerLifecycle(){if(registered)return;ServerTickEvents.END_SERVER_TICK.register(WarheadImpactChunkLeaseManager::tick);ServerLifecycleEvents.SERVER_STOPPED.register(server->clear());registered=true;}public static synchronized void hold(ServerLevel level,UUID effectId,Vec3 impact,int ticks){release(level,effectId);HashSet<ChunkPos> chunks=new HashSet<>();IcbmChunkTicketRegistry.addWindow(chunks,IcbmChunkTicketRegistry.chunk(impact),IcbmConstants.IMPACT_CHUNK_RADIUS);for(ChunkPos chunk:chunks)IcbmChunkTicketRegistry.acquire(level,chunk);LEASES.computeIfAbsent(level,ignored->new HashMap<>()).put(effectId,new Lease(Set.copyOf(chunks),level.getGameTime()+Math.max(1,ticks)));}public static synchronized void release(ServerLevel level,UUID id){Map<UUID,Lease> leases=LEASES.get(level);if(leases==null)return;Lease lease=leases.remove(id);if(lease!=null)for(ChunkPos chunk:lease.chunks())IcbmChunkTicketRegistry.release(level,chunk);if(leases.isEmpty())LEASES.remove(level);}private static synchronized void tick(MinecraftServer server){for(ServerLevel level:server.getAllLevels()){Map<UUID,Lease> leases=LEASES.get(level);if(leases==null)continue;for(UUID id:new ArrayList<>(leases.keySet()))if(level.getGameTime()>=leases.get(id).expiresAt())release(level,id);}}private static synchronized void clear(){for(var levelEntry:LEASES.entrySet())for(Lease lease:levelEntry.getValue().values())for(ChunkPos chunk:lease.chunks())IcbmChunkTicketRegistry.release(levelEntry.getKey(),chunk);LEASES.clear();}private record Lease(Set<ChunkPos> chunks,long expiresAt){} }